import{_t as e,it as t,n,rt as r}from"./chunks/framework.yS8CksER.js";var i=JSON.parse(`{"title":"Rollen und Berechtigungen","description":"","frontmatter":{"title":"Rollen und Berechtigungen","covers":{"screens":[],"stories":["US-143","US-147"]}},"headers":[],"relativePath":"de/administration/roles-and-permissions.md","filePath":"de/administration/roles-and-permissions.md"}`),a={name:`de/administration/roles-and-permissions.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="rollen-und-berechtigungen" tabindex="-1">Rollen und Berechtigungen <a class="header-anchor" href="#rollen-und-berechtigungen" aria-label="Permalink to “Rollen und Berechtigungen”">​</a></h1><p>Jede Operation von OEA verlangt eine Berechtigung, und Berechtigungen kommen nur aus Rollen. OEA liefert einen festen Berechtigungskatalog und eingebaute Rollen aus; <code>GET /admin/permissions</code> und <code>GET /admin/roles</code> geben sie zurück.</p><h2 id="eingebaute-rollen" tabindex="-1">Eingebaute Rollen <a class="header-anchor" href="#eingebaute-rollen" aria-label="Permalink to “Eingebaute Rollen”">​</a></h2><table tabindex="0"><thead><tr><th>Rolle</th><th>Berechtigungen</th><th>Für</th></tr></thead><tbody><tr><td><code>portal-reader</code></td><td><code>portal:read</code></td><td>geteilte Inhalte im Portal lesen</td></tr><tr><td><code>viewer</code></td><td><code>portal:read</code>, <code>entity:read</code></td><td>das Repository lesen</td></tr><tr><td><code>analyst</code></td><td><code>viewer</code> + <code>analytics:query</code></td><td>Analytics-Abfragen</td></tr><tr><td><code>enterprise-architect</code></td><td><code>viewer</code> + <code>entity:write</code>, <code>entity:delete</code>, <code>entity:restore</code>, <code>catalog:manage</code>, <code>dashboard:manage</code>, <code>viewpoint:manage</code>, <code>plateau:go-live</code>, <code>webhook:manage</code></td><td>die Architektur pflegen</td></tr><tr><td><code>integration-writer</code></td><td><code>entity:read</code>, <code>entity:write</code></td><td>Integrationen, die Entitäten schreiben</td></tr><tr><td><code>auditor</code></td><td><code>audit:read</code></td><td>das Audit-Log lesen und prüfen</td></tr><tr><td><code>metamodel-admin</code></td><td><code>metamodel:write</code></td><td>das Metamodell ändern und importieren</td></tr><tr><td><code>security-admin</code></td><td><code>visibility:configure</code>, <code>visibility-scope:assign</code>, <code>role:assign</code>, <code>person:manage</code></td><td>Sichtbarkeitsregeln, Personen und Rollen</td></tr><tr><td><code>system-admin</code></td><td><code>role:assign</code>, <code>person:manage</code>, <code>service-account:manage</code>, <code>auth-config:manage</code>, <code>settings:manage</code></td><td>die Instanz administrieren</td></tr></tbody></table><p>Das lokale Systemadmin-Konto hat die Rolle <code>system-admin</code>. <strong>Privilegierte Rollen</strong> – Rollen mit einer Berechtigung der Admin-Klasse (<code>metamodel:write</code>, <code>visibility:configure</code>, <code>visibility-scope:assign</code>, <code>role:assign</code>, <code>person:manage</code>, <code>service-account:manage</code>, <code>auth-config:manage</code>, <code>settings:manage</code>) – wirken nur in einer Sitzung, die mit einem zweiten Faktor bestätigt ist. Bei einer Anmeldung über einen Identity-Provider muss der Provider den zweiten Faktor in <code>amr</code> melden.</p><h2 id="rollen-uber-idp-gruppen-vergeben" tabindex="-1">Rollen über IdP-Gruppen vergeben <a class="header-anchor" href="#rollen-uber-idp-gruppen-vergeben" aria-label="Permalink to “Rollen über IdP-Gruppen vergeben”">​</a></h2><p>Du vergibst Rollen, indem du eine Gruppe des Identity-Providers einer Rolle zuordnest. Jede Person in dieser Gruppe bekommt die Rolle bei ihrer nächsten Anmeldung:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">authProviderId</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PROVIDER</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">groupIdentifier</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;group-uuid&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">roleId</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">viewer</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/admin/idp-group-mappings&quot;</span></span></code></pre></div><ul><li>Die Gruppenkennung muss die unveränderliche UUID der Gruppe sein (die Gruppen-Objekt-ID von Entra ID, Authentik und Keycloak); Anzeigenamen werden mit <code>422</code> abgelehnt.</li><li>Eine Person kann keine Gruppe zuordnen, die in ihrem eigenen Groups-Claim enthalten ist (Funktionstrennung).</li><li><code>GET /admin/idp-group-mappings</code> listet die Zuordnungen; <code>PUT</code> und <code>DELETE /admin/idp-group-mappings/{mappingId}</code> ändern und entfernen eine.</li><li>Wie die erste Identitätsbindung beendet auch die erste Gruppenzuordnung die Setup-Phase.</li></ul><h2 id="wenn-sich-die-gruppenmitgliedschaft-andert" tabindex="-1">Wenn sich die Gruppenmitgliedschaft ändert <a class="header-anchor" href="#wenn-sich-die-gruppenmitgliedschaft-andert" aria-label="Permalink to “Wenn sich die Gruppenmitgliedschaft ändert”">​</a></h2><p>OEA wertet die Gruppenmitgliedschaft mit dem Refresh-Token des Providers spätestens 15 Minuten nach der vorherigen Auswertung neu aus: Entfernst du eine Person beim Provider aus einer Gruppe, ist die abgeleitete Rolle innerhalb von 15 Minuten weg. Ohne Refresh-Token, bei einem nicht erreichbaren Provider oder bei einem fehlenden oder abgeschnittenen Groups-Claim gilt keine vom IdP abgeleitete Rolle (Audit-Event <code>auth.idp-groups-unusable</code>).</p><p>Eine über einen Identity-Provider aufgebaute Sitzung endet beim ersten der folgenden Ereignisse: 30 Minuten ohne Aktivität, 12 Stunden nach der Anmeldung oder Ablauf oder Ablehnung des Refresh-Tokens. OEA verlängert nie ein Token des Providers.</p>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};